# -*- coding: utf-8 -*-
from pathlib import Path
from html import escape
root=Path(__file__).resolve().parents[1]
md=(root/'series/investing/months/2005-01.md').read_text()
parts=md.split('\n## ')[1:]
sections=[]
for i,part in enumerate(parts,1):
 title,body=part.split('\n',1)
 paras=[p.strip().replace('\n',' ') for p in body.strip().split('\n\n')]
 sections.append('<section class="chapter"><div class="chapter-number">%02d</div><div><h2>%s</h2>%s</div></section>'%(i,escape(title),''.join('<p>%s</p>'%escape(p) for p in paras)))
